class RulesScreen extends StatefulWidget { final String role; const RulesScreen({super.key, required this.role}); @override State<RulesScreen> createState()=>_RulesScreenState(); }
class _RulesScreenState extends State<RulesScreen> { List<Map<String,dynamic>> rules=[]; final _pc=TextEditingController(); String _cat='اخرى',_type='اخرى'; @override void initState(){ super.initState(); _load(); } Future<void> _load() async { final db=await DatabaseHelper.database; final r=await db.query('classification_rules',orderBy:'priority ASC'); setState(()=>rules=r); } Future<void> _add() async { if(_pc.text.isEmpty) return; final db=await DatabaseHelper.database; await db.insert('classification_rules',{'pattern':_pc.text,'category':_cat,'type':_type,'priority':rules.length+1}); _pc.clear(); _load(); } @override Widget build(BuildContext context){ return Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('البصمات - rules',style:GoogleFonts.cairo(fontSize:22,fontWeight:FontWeight.bold,color:primaryColor)), const SizedBox(height:12), if(widget.role=='super_admin'||widget.role=='admin') Row(children:[Expanded(child:TextField(controller:_pc,decoration:InputDecoration(hintText:'النمط %PDF / FFD8 / PK',border:OutlineInputBorder()))), const SizedBox(width:8), DropdownButton<String>(value:_cat,items:categoriesAr.map((e)=>DropdownMenuItem(value:e,child:Text(e,style:GoogleFonts.cairo()))).toList(),onChanged:(v)=>setState(()=>_cat=v!)), const SizedBox(width:8), DropdownButton<String>(value:_type,items:typesAr.map((e)=>DropdownMenuItem(value:e,child:Text(e,style:GoogleFonts.cairo()))).toList(),onChanged:(v)=>setState(()=>_type=v!)), const SizedBox(width:8), ElevatedButton(onPressed:_add,style:ElevatedButton.styleFrom(backgroundColor:primaryColor),child:Text('اضافة',style:GoogleFonts.cairo(color:Colors.white)))]), const SizedBox(height:16), Expanded(child:ListView.builder(itemCount:rules.length,itemBuilder:(ctx,i)=>Card(child:ListTile(title:Text('Pattern: '+(rules[i]['pattern']??''),style:GoogleFonts.cairo(fontWeight:FontWeight.bold)),subtitle:Text((rules[i]['category']??'')+' / '+(rules[i]['type']??'')+' - '+rules[i]['priority'].toString(),style:GoogleFonts.cairo()),trailing:widget.role=='super_admin'?IconButton(icon:Icon(Icons.delete,color:Colors.red),onPressed:()async{ final db=await DatabaseHelper.database; await db.delete('classification_rules',where:'id=?',whereArgs:[rules[i]['id']]); _load(); }):null))))])); } }
class UsersScreen extends StatefulWidget { @override State<UsersScreen> createState()=>_UsersScreenState(); }
class _UsersScreenState extends State<UsersScreen> { List<Map<String,dynamic>> users=[]; final _u=TextEditingController(); final _p=TextEditingController(); String _r='viewer'; @override void initState(){ super.initState(); _load(); } Future<void> _load() async { final db=await DatabaseHelper.database; final r=await db.query('users',orderBy:'id ASC'); setState(()=>users=r); } Future<void> _add() async { if(_u.text.isEmpty||_p.text.isEmpty) return; final db=await DatabaseHelper.database; final h=sha256.convert(utf8.encode(_p.text)).toString(); try{ await db.insert('users',{'username':_u.text,'password_hash':h,'role':_r,'created_at':DateTime.now().toIso8601String()}); _u.clear(); _p.clear(); _load(); } catch(e){ ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('خطأ: '+e.toString()))); } } @override Widget build(BuildContext context){ return Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('المستخدمين - super_admin فقط',style:GoogleFonts.cairo(fontSize:22,fontWeight:FontWeight.bold,color:primaryColor)), const SizedBox(height:12), Row(children:[Expanded(child:TextField(controller:_u,decoration:InputDecoration(labelText:'اسم المستخدم',border:OutlineInputBorder()))), const SizedBox(width:8), Expanded(child:TextField(controller:_p,decoration:InputDecoration(labelText:'كلمة المرور',border:OutlineInputBorder()))), const SizedBox(width:8), DropdownButton<String>(value:_r,items:['super_admin','admin','user','viewer'].map((e)=>DropdownMenuItem(value:e,child:Text(e,style:GoogleFonts.cairo()))).toList(),onChanged:(v)=>setState(()=>_r=v!)), const SizedBox(width:8), ElevatedButton(onPressed:_add,style:ElevatedButton.styleFrom(backgroundColor:primaryColor),child:Text('اضافة',style:GoogleFonts.cairo(color:Colors.white)))]), const SizedBox(height:16), Expanded(child:ListView.builder(itemCount:users.length,itemBuilder:(ctx,i)=>Card(child:ListTile(leading:CircleAvatar(backgroundColor:primaryColor,child:Text(users[i]['username'][0].toUpperCase(),style:TextStyle(color:Colors.white))),title:Text(users[i]['username'],style:GoogleFonts.cairo()),subtitle:Text('الدور: '+users[i]['role']+' - '+users[i]['created_at'],style:GoogleFonts.cairo(fontSize:11)),trailing:IconButton(icon:Icon(Icons.delete,color:Colors.red),onPressed:users[i]['username']=='admin'?null:()async{ final db=await DatabaseHelper.database; await db.delete('users',where:'id=?',whereArgs:[users[i]['id']]); _load(); }))))])); } }
class SettingsScreen extends StatefulWidget { final String role; final Map<String,dynamic> session; const SettingsScreen({super.key, required this.role, required this.session}); @override State<SettingsScreen> createState()=>_SettingsScreenState(); }
class _SettingsScreenState extends State<SettingsScreen> { String rootPath=''; String lang='ar'; List<Map<String,dynamic>> logs=[]; @override void initState(){ super.initState(); _load(); } Future<void> _load() async { rootPath=await StorageManager.getRootPath(); final prefs=await SharedPreferences.getInstance(); lang=prefs.getString('app_lang')??'ar'; final db=await DatabaseHelper.database; logs=await db.query('login_logs',orderBy:'timestamp DESC',limit:20); setState((){}); } Future<void> _changeRoot() async { final ctrl=TextEditingController(text:rootPath); final res=await showDialog<String>(context:context,builder:(ctx)=>AlertDialog(title:Text('مسار التخزين',style:GoogleFonts.cairo()),content:TextField(controller:ctrl),actions:[TextButton(onPressed:()=>Navigator.pop(ctx),child:Text('الغاء',style:GoogleFonts.cairo())), ElevatedButton(onPressed:()=>Navigator.pop(ctx,ctrl.text),child:Text('حفظ',style:GoogleFonts.cairo()))])); if(res!=null&&res.isNotEmpty){ await StorageManager.setRootPath(res); _load(); } } Future<void> _backup() async { try{ final root=await StorageManager.getRootPath(); final dbPath=await StorageManager.getDatabasePath(); final backupDir=Directory(root+'backup'); if(!await backupDir.exists()) await backupDir.create(recursive:true); final zipPath=root+'backup/backup_'+DateFormat('yyyy-MM-dd_HH-mm').format(DateTime.now())+'.zip'; final archive=Archive(); if(await File(dbPath).exists()){ final data=await File(dbPath).readAsBytes(); archive.addFile(ArchiveFile('smartdms.db',data.length,data)); } final configDir=Directory(root+'config'); if(await configDir.exists()){ await for(var f in configDir.list()){ if(f is File){ final data=await f.readAsBytes(); archive.addFile(ArchiveFile('config/'+p.basename(f.path),data.length,data)); } } } final zipData=ZipEncoder().encode(archive); await File(zipPath).writeAsBytes(zipData!); if(mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('تم النسخ: '+zipPath,style:GoogleFonts.cairo()))); } catch(e){ if(mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('فشل: '+e.toString()))); } } Future<void> _vacuum() async { final db=await DatabaseHelper.database; await db.execute('VACUUM'); if(mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('تم VACUUM',style:GoogleFonts.cairo()))); } @override Widget build(BuildContext context){ return SingleChildScrollView(padding:const EdgeInsets.all(20),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('الاعدادات - فاتح فقط #F5F7FB',style:GoogleFonts.cairo(fontSize:22,fontWeight:FontWeight.bold,color:primaryColor)), const SizedBox(height:16), Card(child:ListTile(title:Text('الحساب',style:GoogleFonts.cairo(fontWeight:FontWeight.bold)),subtitle:Text('المستخدم: '+widget.session['username'].toString()+' - الدور: '+widget.role,style:GoogleFonts.cairo()))), Card(child:ListTile(title:Text('مسار التخزين ROOT',style:GoogleFonts.cairo(fontWeight:FontWeight.bold)),subtitle:Text(rootPath,style:GoogleFonts.cairo(fontSize:12)),trailing:ElevatedButton(onPressed:_changeRoot,child:Text('تغيير',style:GoogleFonts.cairo())))), Card(child:ListTile(title:Text('نسخ احتياطي ZIP',style:GoogleFonts.cairo(fontWeight:FontWeight.bold)),subtitle:Text('ينسخ الى {ROOT}/backup/',style:GoogleFonts.cairo(fontSize:11)),trailing:ElevatedButton(onPressed:_backup,style:ElevatedButton.styleFrom(backgroundColor:Colors.green),child:Text('نسخ',style:GoogleFonts.cairo(color:Colors.white))))), Card(child:ListTile(title:Text('صيانة DB VACUUM',style:GoogleFonts.cairo(fontWeight:FontWeight.bold)),trailing:ElevatedButton(onPressed:_vacuum,style:ElevatedButton.styleFrom(backgroundColor:Colors.orange),child:Text('VACUUM',style:GoogleFonts.cairo(color:Colors.white))))), Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('معلومات',style:GoogleFonts.cairo(fontWeight:FontWeight.bold)), Text('SmartDMS PRO V1.0\nROOT/database/smartdms.db\nROOT/files/{YYYY}/{CATEGORY}/{TYPE}/{SMART_NAME}\nبصمة 8 بايت %PDF/FFD8/PK\nUX: RTL عربي, سايد بار يمين 280 ابيض, اساسي #0D47A1, خلفية #F5F7FB, خط Cairo',style:GoogleFonts.cairo(fontSize:12))]))), Card(child:Padding(padding:const EdgeInsets.all(12),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('الامان',style:GoogleFonts.cairo(fontWeight:FontWeight.bold)), Text('super_admin: كل شيء, admin: اضافة+نقل+بحث+معاينة+احصائيات, user: اضافة وعرض, viewer: عرض وبحث فقط',style:GoogleFonts.cairo(fontSize:12)), const SizedBox(height:8), Text('سجل الدخول آخر 20:',style:GoogleFonts.cairo(fontWeight:FontWeight.bold,fontSize:12)), ...logs.map((e)=>Text((e['timestamp']??'').toString()+' - '+(e['username']??'')+' - '+(e['action']??''),style:GoogleFonts.cairo(fontSize:11)))]))), Card(child:ListTile(title:Text('اللغة',style:GoogleFonts.cairo(fontWeight:FontWeight.bold)),subtitle:Text('العربية RTL',style:GoogleFonts.cairo()),trailing:DropdownButton<String>(value:lang,items:[DropdownMenuItem(value:'ar',child:Text('العربية',style:GoogleFonts.cairo())), DropdownMenuItem(value:'en',child:Text('English',style:GoogleFonts.cairo()))],onChanged:(v)async{ final prefs=await SharedPreferences.getInstance(); await prefs.setString('app_lang',v!); setState(()=>lang=v); })))])); } }
